INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'Chemistry', 'Unit 4', 'Molarum Grade 10 — Chemistry ENERGY CHANGES AND ELECTROCHEMISTRY', 'Source-grounded Molarum Grade 10 Chemistry questions for ENERGY CHANGES AND ELECTROCHEMISTRY.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('6d47ac35-4719-4115-8e21-2f23326f04a9'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'In a galvanic cell, which statement is correct about the electrodes and electron flow?', 'Oxidation occurs at the anode', 'In galvanic cells, oxidation occurs at the anode and reduction occurs at the cathode; electrons flow from the anode to the cathode through the external circuit.', 0),('ccd9d67c-5720-4451-85b1-1a59408e8663'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'Why do electrolyte solutions conduct electricity?', 'Because ions are present and can migrate', 'Conductivity in solutions arises from the movement of ions that carry charge.', 1),('94c44929-7017-4eb0-8858-05d428fa6ee3'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'true_false', 'In electrolysis, the electrical energy is used to drive a non-spontaneous chemical reaction.', 'True', 'Electrolysis requires external electrical energy to drive reactions that are not spontaneous.', 2),('d93232e0-d1d1-428a-8952-356bc1555ada'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'In a galvanic (Voltaic) cell, which statement is true about the cathode and the reduction reaction?', 'The cathode is where reduction occurs', 'In galvanic cells, oxidation takes place at the anode and reduction at the cathode; electrons flow from anode to cathode via the external circuit.', 3),('7dc6b102-5ea1-4bec-8afc-2744bd893085'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'According to Faraday''s laws, when you increase the current while keeping time constant, the amount deposited at the electrodes:', 'Increases with current', 'The amount deposited is proportional to the total charge Q = I t; higher current delivers more charge in the same time.', 4),('c4b27933-a220-44a0-801f-5a597b765882'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Name the part of the electrochemical cell where oxidation occurs.', 'Anode', 'Oxidation occurs at the anode; reduction occurs at the cathode.', 5),('2917d0a2-c00a-4aa3-808a-437ec52d3ac7'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Describe how the flow of electrons is related to the spontaneous redox reaction inside a galvanic cell.', 'Electrons flow from the anode (where oxidation occurs) to the cathode (where reduction occurs); the spontaneous redox reaction provides the driving force.', 'The spontaneous redox reaction drives electron flow through the external circuit from anode to cathode.', 6),('42152011-a18a-44ee-8bf6-698ebb8c0535'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'A 9.0 V electrolysis setup draws a current of 0.75 A for 3600 seconds. Calculate the total electrical energy supplied in joules. Provide the method and final unit.', '24300 J', 'Energy E = V × I × t; E = 9 V × 0.75 A × 3600 s = 24300 J.', 7),('399e2b28-29cb-405b-8616-9b16322a6777'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'During electrolysis, a constant current of 0.40 A is applied for 900 s to deposit a metal that requires 2 electrons per atom. Using Faraday''s constant (96485 C/mol e-), calculate the moles of metal deposited. Provide steps and final unit.', '0.00187 mol', 'Q = I t = 0.40 A × 900 s = 360 C; moles e- = Q/F = 360/96485 ≈ 3.73e-3 mol e-; metal deposited = (3.73e-3)/2 ≈ 1.865e-3 mol.', 8),('49e15cde-f24b-42b5-8d8f-b898191e7057'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'Using the Nernst equation, if E° = 1.10 V, n = 2, and Q = 10 at 25°C, what is E? (choose the closest value)', '1.07 V', 'E = E° − (0.0592/n) log Q = 1.10 − (0.0592/2) log 10 ≈ 1.10 − 0.0296 × 1 ≈ 1.070 V.', 9),('5213dd4d-83ee-4f6f-8d52-75adbc2e4069'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'In a galvanic (Voltaic) cell, what happens at the anode?', 'Oxidation occurs and electrons are released', 'The anode is the site of oxidation in a galvanic cell; electrons flow from the anode through the external circuit to the cathode.', 10),('7058dc16-0a74-4944-8f57-730d0161ed2f'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'What is the function of the salt bridge in a galvanic cell?', 'It maintains electrical neutrality by allowing ion flow between solutions', 'The salt bridge permits ion movement to balance charges as electrons flow in the external circuit.', 11),('97449259-817a-4ef7-8c3c-8955bb66197d'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'An electrolyte solution conducts electricity because it contains', 'Free ions', 'In electrolytes, ions move to carry charge and enable current.', 12),('4615f799-b199-40ef-8b56-3da61a44d74e'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'In a galvanic cell, the electrode at which reduction occurs is the', 'Cathode', 'Reduction occurs at the cathode in a galvanic cell.', 13),('342b04c0-d404-4719-8105-732bd7da9f8c'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'During electrolysis of molten NaCl, which products are formed at the cathode and anode, respectively?', 'Na (cathode) and Cl2 (anode)', 'Cathode reduction yields sodium metal; anode oxidation yields chlorine gas in molten NaCl.', 14),('b20fe8cb-5a19-4173-8dfa-75f4e1b2c69c'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'true_false', 'In electrolysis, an external power source drives the redox reaction.', 'True', 'Electrolysis requires external energy to drive non-spontaneous reactions.', 15),('269225fd-55ae-4602-81d7-f65979b07c8a'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Define a galvanic (Voltaic) cell and give one real-world example.', 'A galvanic (Voltaic) cell is an electrochemical cell in which spontaneous redox reactions convert chemical energy into electrical energy; example: a dry cell battery (life of a small flashlight or a standard AA battery).', 'It converts chemical energy to electrical energy via spontaneous redox; real-world example: common batteries.', 16),('f1b5f52a-9087-4156-821a-fab951674551'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Explain how a salt bridge maintains charge balance in a galvanic cell.', 'The salt bridge allows ions to flow to balance charge buildup as electrons leave one half-cell and enter the other; cations migrate toward the cathode and anions toward the anode to keep solutions electrically neutral.', 'Ion flow from the salt bridge maintains electrical neutrality during sustained redox reactions in the half-cells.', 17),('0a2d39f7-957f-424a-892b-73ba32a7eb0c'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Electrolysis of molten NaCl: A current of 5.0 A is passed for 30.0 s. How many grams of Na metal are produced at the cathode? Show all steps and final unit.', '0.0358 g Na', 'Calculation steps: Q = I t = 5.0 A × 30.0 s = 150 C; moles e− = Q / F = 150 / 96485 = 1.556×10^-3 mol; Na+ + e− → Na(s) so moles Na = 1.556×10^-3 mol; mass Na = 1.556×10^-3 mol × 22.99 g/mol ≈ 0.0358 g.', 18),('8f92a393-f5d4-4051-8fe4-0b32b30462d8'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Electrolysis of water: A current of 2.00 A is passed for 600 s. How many moles of H2 gas are produced at the cathode? Show method and final unit.', '6.22×10^-3 mol H2', 'Calculation steps: Q = I t = 2.00 A × 600 s = 1200 C; For water reduction: 2 H+ + 2 e− → H2; moles H2 = Q / (2F) = 1200 / (2 × 96485) ≈ 6.22×10^-3 mol; final unit: moles of H2 (gas).', 19),('62a74977-0950-4e83-8153-a65b14e3241a'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'In a galvanic (voltaic) cell, which statement about energy change is correct?', 'It releases energy to the surroundings', 'Galvanic cells convert chemical energy into electrical energy, releasing energy to the surroundings as electricity.', 20),('a9774d60-fb1e-4472-8b48-b87a685d9e07'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'In a galvanic cell, which statement is true?', 'The anode is the negative electrode and oxidation occurs there', 'In galvanic cells, the anode is negative and oxidation takes place there; electrons flow to the cathode through the external circuit.', 21),('8b807e94-fa27-4c8d-8a70-050ae040a2c3'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'During electrolysis of molten CuCl2, what are the products at the electrodes?', 'Cu at cathode and Cl2 at anode', 'In molten CuCl2, Cu2+ is reduced to Cu metal at the cathode, while Cl− is oxidized to Cl2 at the anode.', 22),('d9fa1fcb-7e70-4121-8006-00ffeeab3d14'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'What does a standard electrode potential indicate?', 'The tendency of a species to gain electrons (be reduced) under standard conditions', 'Standard electrode potentials indicate how readily a species gains electrons (is reduced) under standard conditions.', 23),('ae7c1499-8757-4f18-8b70-26c4fbd3bb4e'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'Which factor increases the conductivity of an electrolyte in solution under typical conditions?', 'Higher ion concentration', 'Higher concentrations of mobile ions generally increase the solution''s ability to conduct electricity.', 24),('146c9f96-34a8-4078-878a-bb669274e997'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'true_false', 'In a galvanic cell, the overall reaction is spontaneous under standard conditions.', 'True', 'Galvanic cells are designed to produce electrical energy spontaneously under standard conditions.', 25),('ca837db4-e954-4577-8cef-72af1c91570d'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Explain the role of the salt bridge in a galvanic cell.', 'It completes the circuit and maintains electrical neutrality by allowing ion flow between half-cells, preventing charge buildup that would stop the reaction.', 'The salt bridge allows ions to move to balance charge as electrons flow through the external circuit.', 26),('f9643fc3-6eb5-4c42-8ddf-3d84e262c042'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Describe one real-world application of electrolysis.', 'Electroplating metals (such as silver or chromium) or extraction of reactive metals using electrolytic reduction.', 'Electrolysis is used in electroplating to deposit a metal layer and in extracting reactive metals from compounds.', 27),('315db603-fcd3-4398-83c7-ad9bc94bf4f7'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Calculate the standard cell potential (E°cell) for a Daniell cell using the standard reduction potentials: Cu2+/Cu = +0.34 V and Zn2+/Zn = -0.76 V. The cell notation is: Zn(s) | Zn2+(aq) || Cu2+(aq) | Cu(s).', '1.10 V', 'E°cell = E°cathode - E°anode = 0.34 - (-0.76) = 1.10 V. Units: volts (V).', 28),('bfe50d77-feb3-4a92-85d1-a1ffee69ce06'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'If 2.00 A is passed for 30.0 minutes through a solution containing Cu2+ to deposit copper at the cathode (n = 2 electrons per Cu), how many grams of Cu are deposited? Use F = 96485 C/mol and M(Cu) = 63.55 g/mol.', '1.18 g Cu', 'I = 2.00 A; t = 30.0 min = 1800 s; Q = It = 3600 C; n = 2; moles Cu = Q/(nF) = 3600/(2×96485) ≈ 0.01863 mol; mass = 0.01863 × 63.55 ≈ 1.184 g. Final ≈ 1.18 g Cu deposited.', 29),('5244df6c-bc5f-4c33-817c-dc05be4afa54'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'Which statement correctly describes energy changes in electrochemical reactions?', 'Energy changes can be either exothermic or endothermic depending on the reaction.', 'Electrochemical processes can release heat or absorb heat, and the overall energy change is linked to the cell potential and thermodynamics.', 30),('ef754eeb-fd36-4709-8863-5774c4bba21e'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'Which components are required in a galvanic (voltaic) cell?', 'Anode, cathode and salt bridge are required components of a galvanic cell.', 'A galvanic cell consists of two electrodes (anode and cathode), an electrolyte, and often a salt bridge to maintain charge balance.', 31),('ba35eaf7-230b-4a7c-8e69-b5c39ded1a59'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'For the galvanic cell represented by Zn(s) | Zn2+(aq, 1 M) || Cu2+(aq, 1 M) | Cu(s), which statement is correct?', 'The reaction as written is spontaneous.', 'Zn is oxidized at the anode and Cu2+ is reduced at the cathode; the overall cell reaction occurs spontaneously, giving E°cell positive.', 32),('905cc9c9-949b-46af-8cda-4d7b99107770'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'During the electrolysis of molten sodium chloride, which product is formed at the cathode?', 'Sodium metal', 'At the cathode, Na+ gains electrons to form Na metal; Cl- is oxidized at the anode to Cl2.', 33),('8cdf0148-28e0-4346-8b13-71fa4c72b22f'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'multiple_choice', 'Which change increases the electrical conductivity of an electrolyte solution?', 'Increase in ion mobility', 'Higher ion mobility allows more charge carriers to move, raising conductivity. Temperature and electrolyte type influence mobility.', 34),('4694edec-084c-49af-8b5d-ac6c167cb747'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'A galvanic cell Zn(s) | Zn2+(aq, 1 M) || Cu2+(aq, 1 M) | Cu(s) has E°cell = +1.10 V at 25°C. If [Zn2+] = 0.010 M and [Cu2+] = 0.10 M, what is the cell potential E? Use the Nernst equation E = E°cell - (0.05916/n) log(Q).', 'E ≈ 1.13 V', 'Reaction: Zn(s) + Cu2+(aq) → Zn2+(aq) + Cu(s). Q = [Zn2+]/[Cu2+] = 0.010/0.10 = 0.10. n = 2. E = 1.10 - (0.05916/2) log(0.10) = 1.10 - 0.02958(-1) ≈ 1.13 V.', 35),('3435238e-c4c2-45a1-83c3-8003ddb792e3'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'During the electrolysis of concentrated sodium chloride solution (brine), 5.0 A of current is passed for 120 s. Assuming Cl2 is evolved at the anode via 2 Cl− → Cl2 + 2 e−, calculate the mass of Cl2 produced. Use F = 96485 C/mol and M(Cl2) = 70.90 g/mol.', 'Approximately 0.22 g of Cl2', 'Charge Q = I t = 5.0 A × 120 s = 600 C. Moles of electrons = Q / F = 600 / 96485 ≈ 0.00621 mol e−. Moles of Cl2 = (0.00621) / 2 ≈ 0.003106 mol. Mass = 0.003106 × 70.90 ≈ 0.22 g.', 36),('40041981-d5ea-451c-8c6a-8acc7173dbca'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'true_false', 'A galvanic cell with a positive standard cell potential E°cell will always be spontaneous at any temperature.', 'False', 'E°cell indicates spontaneity under standard conditions (25°C, 1 M). At other temperatures or concentrations, ΔG = -nFE and spontaneity can change.', 37),('fe7735fd-7dca-4cdb-8026-a3ae258e79c6'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'What is the function of a salt bridge in a galvanic cell?', 'It maintains electrical neutrality by allowing ions to flow between half-cells, preventing charge buildup.', 'The salt bridge completes the circuit by balancing charge as electrons flow through the external circuit.', 38),('765c3e42-e425-49bb-85e6-eaf127f595a7'::uuid, 'fa4f836f-684e-4e51-8ab0-f26527b1a77f'::uuid, 'fill_blank', 'Differentiate between galvanic and electrolytic cells in terms of energy flow and electrode roles.', 'Galvanic cell: chemical energy is converted to electrical energy; reaction is spontaneous (positive E°cell). Electrolytic cell: electrical energy is supplied to drive a non-spontaneous reaction; external power source forces electrons from anode (positive) to cathode (negative).', 'In galvanic cells the cell provides power; in electrolytic cells power is supplied to force non-spontaneous reaction; electrode polarity differs.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
